<section class="panel form-panel"><div class="panel-head"><div><span class="eyebrow">FIXTURE MANAGEMENT</span><h2><?= $match?'Update match':'Schedule a match' ?></h2></div><a class="text-link" href="index.php?route=matches">← Back to matches</a></div><form method="post" action="index.php?route=matches/save" class="form-grid"><?= csrf_field() ?><?php if($match): ?><input type="hidden" name="id" value="<?= e($match['id']) ?>"><?php endif; ?>
<label>Opponent<input name="opponent" required value="<?= e($match['opponent']??'') ?>"></label><label>Date and time<input type="datetime-local" name="match_date" required value="<?= e(isset($match['match_date'])?date('Y-m-d\\TH:i',strtotime($match['match_date'])):'') ?>"></label><label>Venue<input name="venue" required value="<?= e($match['venue']??'') ?>"></label><label>Competition<input name="competition" value="<?= e($match['competition']??'') ?>"></label><label>Our score<input type="number" min="0" name="our_score" value="<?= e($match['our_score']??'') ?>"></label><label>Opponent score<input type="number" min="0" name="opponent_score" value="<?= e($match['opponent_score']??'') ?>"></label><label>Status<select name="status"><?php foreach(['scheduled','completed','cancelled'] as $v): ?><option value="<?= e($v) ?>" <?= (($match['status']??'scheduled')===$v)?'selected':'' ?>><?= e(ucfirst($v)) ?></option><?php endforeach; ?></select></label><div class="wide"><button class="btn">Save match</button></div></form></section>